<?php
require_once __DIR__.'/_common.php';$current_slug='posyandu';require_once ROOT_PATH.'/includes/auth-guard.php';$page_title='Data Posyandu';
$search=trim(isset($_GET['search'])?$_GET['search']:'');$params=array();$where='';if($search!==''){$where=' WHERE p.nama_posyandu LIKE ? OR p.dusun_rw LIKE ? OR w.nama_wilayah LIKE ? OR pk.nama_puskesmas LIKE ?';$pattern='%'.$search.'%';$params=array($pattern,$pattern,$pattern,$pattern);}
$stmt=$pdo->prepare('SELECT p.*,w.nama_wilayah,w.kecamatan,w.kabupaten,pk.nama_puskesmas,(SELECT COUNT(*) FROM anak a WHERE a.id_posyandu=p.id_posyandu) AS jumlah_anak FROM posyandu p JOIN wilayah w ON w.id_wilayah=p.id_wilayah JOIN puskesmas pk ON pk.id_puskesmas=p.id_puskesmas'.$where.' ORDER BY p.nama_posyandu');$stmt->execute($params);$records=$stmt->fetchAll();$flash=get_flash();require ROOT_PATH.'/includes/header.php';
?>
