<div class="card"><div class="card-body"><form class="row g-2 mb-3"><div class="col-md-9"><input class="form-control" name="search" placeholder="Cari posyandu, dusun/RW, wilayah, atau puskesmas..." value="<?= e($search) ?>"></div><div class="col-md-3 d-grid"><button class="btn btn-outline-primary">Cari</button></div></form><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Posyandu</th><th>Dusun / RW</th><th>Wilayah</th><th>Puskesmas Induk</th><th>Anak Terdaftar</th><th class="text-end">Aksi</th></tr></thead><tbody><?php if(!$records): ?><tr><td colspan="6" class="text-center text-muted py-4">Belum ada data posyandu yang cocok.</td></tr><?php endif;foreach($records as $r): ?><tr><td class="fw-semibold"><?= e($r['nama_posyandu']) ?><div class="small text-muted"><?= e($r['alamat']?:'Alamat belum diisi') ?></div></td><td><?= e($r['dusun_rw']?:'-') ?></td><td><?= e($r['nama_wilayah']) ?><div class="small text-muted"><?= e($r['kecamatan'].', '.$r['kabupaten']) ?></div></td><td><?= e($r['nama_puskesmas']) ?></td><td><?= (int)$r['jumlah_anak'] ?></td><td class="text-end text-nowrap"><a class="btn btn-sm btn-outline-secondary" href="<?= posyandu_url('edit.php',array('id'=>$r['id_posyandu'])) ?>" title="Ubah"><i class="bi bi-pencil"></i></a> <a class="btn btn-sm btn-outline-danger" href="<?= posyandu_url('hapus.php',array('id'=>$r['id_posyandu'])) ?>" title="Hapus"><i class="bi bi-trash"></i></a></td></tr><?php endforeach; ?></tbody></table></div></div></div>
